 const star=(x,y,r,col,angle=0)=>at(x,y,1,angle,()=>poly(Array.from({length:10},(_,j)=>{const a=-Math.PI/2+j*TAU/10,rr=j%2?r*.46:r;return[Math.cos(a)*rr,Math.sin(a)*rr];}),col));
