  const y=e.key==='respawn'?520:480,r=112+power*9+m.impact*18;
  const g=c.createRadialGradient(x,y,10,x,y,r);g.addColorStop(0,col+'38');g.addColorStop(.5,col+'12');g.addColorStop(1,col+'00');
